sections.code:
.carte { position: relative; }
.badge {
  position: absolute;
  top: 8px;
  right: 8px;
}

questions.code:
.carte {
  transform: translateX(0);
}
.modale {
  position: fixed;
  inset: 0;
  z-index: 9999;
}

.menu {
  z-index: 10;
  background: white;
}
.contenu {
  position: relative;
  z-index: 1;
}

.a { position: relative; z-index: 1; }
.enfant { position: relative; z-index: 999; }
.b { position: relative; z-index: 2; }

sections.code:
:root { --fond: white; --texte: #111; }
@media (prefers-color-scheme: dark) {
  :root { --fond: #111; --texte: #eee; }
}
body {
  background: var(--fond);
  color: var(--texte);
}

questions.code:
@keyframes glisser {
  from { left: 0; }
  to   { left: 300px; }
}
.panneau {
  position: absolute;
  animation: glisser 300ms;
}
